impl crate::documents::Document {
    pub async fn find_unique<'e, E>(
        executor: E,
        w: &crate::documents::DocumentWhereUniqueInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let cols = "\"id\", \"user_id\", \"file_name\", \"mime_type\", \"file_size\", \"page_count\", \"created_at\", \"updated_at\", \"uploaded_at\", \"billed_at\", \"deleted_at\", \"delete_document\", \"is_frozen\", \"paid\", \"invoice_id\", \"demand_letter_id\", \"document_type\", \"case_id\", \"firm_id\", \"illegible_pages\", \"tags\"";
        let mut qb =
            sqlx::QueryBuilder::new(format!(r#"SELECT {} FROM "documents" WHERE "#, cols,));
        // For v1, support only the @id field. Composite uniques are out of scope.
        // The WhereUniqueInput has Option<T> per @id/@unique field; we pick the
        // first Some(). Multi-Some inputs cover composite uniques — TODO Task v2.
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(value.clone());
        } else {
            return Ok(None);
        }
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

