impl crate::documents::Document {
    pub async fn create_many<'e, E>(
        executor: E,
        inputs: &[crate::documents::DocumentUncheckedCreateInput],
    ) -> sqlx::Result<u64>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        if inputs.is_empty() {
            return Ok(0);
        }
        let mut qb = sqlx::QueryBuilder::new(
            r#"INSERT INTO "documents" ("id", "user_id", "file_name", "mime_type", "billed_at", "deleted_at", "invoice_id", "demand_letter_id", "tags") "#,
        );
        qb.push_values(inputs, |mut row, input| {
            row.push_bind(input.id.clone());
            row.push_bind(input.user_id.clone());
            row.push_bind(input.file_name.clone());
            row.push_bind(input.mime_type.clone());
            row.push_bind(input.billed_at);
            row.push_bind(input.deleted_at);
            row.push_bind(input.invoice_id.clone());
            row.push_bind(input.demand_letter_id.clone());
            row.push_bind(input.tags.clone());
        });
        let result = qb.build().execute(executor).await?;
        Ok(result.rows_affected())
    }
}

